'use strict';
function movementFamily(m){
 const name=m.name.toLowerCase(),pattern=m.pattern;
 if(/clean.*jerk/.test(name))return ['clean-jerk','Clean & jerk'];if(/snatch/.test(name))return ['snatch','Snatches'];if(/clean.*press/.test(name))return ['clean-press','Clean & press'];
 if(/farmer/.test(name)&&/carry/.test(name))return ['farmer','Farmer’s carries'];if(/suitcase/.test(name)&&/carry/.test(name))return ['suitcase','Suitcase carries'];if(/march/.test(name))return ['march','Marching variations'];
 if(m.group==='calves')return ['calf','Calf raises'];if(/hamstring walkout/.test(name))return ['walkout','Hamstring walkouts'];
 if(/push-up/.test(name))return ['pushup','Push-ups'];if(/floor press/.test(name))return ['floor-press','Floor presses'];if(m.group==='press'&&/press/.test(name))return ['chest-press','Chest presses'];
 if(/lateral raise|scaption/.test(name))return ['lateral-raise','Lateral raises'];if(/front raise/.test(name)&&m.group==='shoulder')return ['front-raise','Front raises'];if(/face pull/.test(name))return ['face-pull','Face pulls'];
 if(/plank/.test(name))return ['plank','Planks'];if(/dead bug/.test(name))return ['deadbug','Dead bugs'];if(/hollow/.test(name))return ['hollow','Hollow holds & rocks'];if(/crunch/.test(name))return ['crunch','Crunches'];
 if(/hip thrust/.test(name))return ['hipthrust','Hip thrusts'];if(/bridge/.test(name))return ['bridge','Glute bridges'];if(/frog pump/.test(name))return ['frog','Frog pumps'];if(/romanian|stiff-legged|kickstand.*hinge|single-leg.*hinge/.test(name))return ['rdl','Romanian deadlifts & single-leg hinges'];if(/deadlift/.test(name))return ['deadlift','Deadlifts'];if(/good morning/.test(name))return ['goodmorning','Good mornings'];
 if(m.group==='triceps'){if(/pushdown/.test(name))return ['pushdown','Triceps pushdowns'];if(/kickback/.test(name))return ['kickback','Triceps kickbacks'];if(/overhead/.test(name))return ['triceps-overhead','Overhead triceps extensions'];}
 const families={'row':['row','Rows'],'pulldown':['pulldown','Pulldowns'],'straight-arm pulldown':['pullover','Pullovers & straight-arm pulldowns'],'overhead press':['shoulder-press','Shoulder presses'],'chest fly':['fly','Chest fly variations'],'rear delt fly':['rear-fly','Rear-delt fly variations'],'shoulder rotation':['cuff','Shoulder rotations'],'squat':['squat','Squats'],'lunge':['lunge','Lunges'],'split squat':['split','Split squats'],'step-up':['stepup','Step-ups'],'step-down':['stepdown','Step-downs'],'isometric knee extension':['wallsit','Wall sits'],'knee extension':['legextension','Knee extensions'],'knee flexion':['hamcurl','Hamstring curls'],'elbow flexion':['curl','Biceps curls'],'hip abduction':['abduction','Hip abduction variations'],'hip adduction':['adduction','Hip adduction variations']};
 return families[pattern]||['move-'+m.id,m.name];
}
function groupedChoices(choices){const groups=new Map();for(const m of choices){const [key,label]=movementFamily(m),id=m.group+':'+key;if(!groups.has(id))groups.set(id,{id,label,group:m.group,choices:[]});groups.get(id).choices.push(m);}return [...groups.values()];}
function renderChoiceFamilies(choices,renderRow){return groupedChoices(choices).map(f=>f.choices.length===1?renderRow(f.choices[0]):`<details class="exercise-family" data-exercise-family><summary><span><strong>${esc(f.label)}</strong><small>${esc(MUSCLE_GROUPS[f.group])} · <span data-family-count>${f.choices.length}</span> variants</small></span><span class="family-open-label">View variants</span></summary><div class="family-variants">${f.choices.map(renderRow).join('')}</div></details>`).join('');}
